@hom_eval₂ : ∀ {R : Type u_4} {S₁ : Type u_5} {S₂ : Type u_6} {σ : Type u_7} [inst : CommSemiring R]
  [inst_1 : CommSemiring S₁] [inst_2 : CommSemiring S₂] (p : MvPolynomial σ R) (f : R →+* S₁) (φ : S₁ →+* S₂)
